// Traegt hier jeweils die Zeilen ein, deren contentStage manuell zurueckgesetzt werden soll.
// 2026-07-28 (5. Verwendung): vol_10731 (2026/152-01) - P4s AI-Content-Aufruf hatte
// website.article/instagram.caption mit Inhalten eines ANDEREN Vorgangs (2026/179) vermischt
// (siehe P4 Parse Content JSON Fix, per-Feld-Grounding-Check), obwohl pressStatement/Bild
// korrekt waren. wordpressGoslarPosted war noch null (nicht gepostet) - sicherer Reset ohne
// Risiko eines Duplikat-Posts. imageHeadline/imageSubline werden diesmal NICHT zurueckgesetzt,
// da das bereits komponierte Bild (imageStage=composed) korrekt und nicht betroffen war -
// nur der Text soll neu generiert werden, das Bild bleibt unangetastet.
const TARGETS = [
  { vorgangKey: 'vol_10731', vorgangsnummer: '2026/152-01', targetStage: 'needs_content' }
];

if (!TARGETS.length) {
  throw new Error('[ContentStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    contentStage: t.targetStage || 'needs_summary',
    headlineChoiceStage: '',
    visualPromptStage: '',
    judgmentChainProcessedAt: '',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
